mapper.insert:
update
    t_groups
set groups_person_number = groups_person_number + #{number}
where id = #{groupId}

mapper.select:
select ifnull(sum(groups_person_number),0)
from t_groups
where is_deleted = 0 and experiment_id = #{experimentId}

select id
from t_groups
where is_deleted = 0 and experiment_id = #{planId}

select
    max(create_date)
from t_experiment_progress
where experiment_id = #{experimentId}
  and groups_id = #{groupsId}
  and element_id = #{elementId}
  and user_id = #{userId}
